def wait_for_submit_drain(connection_id, function_name, next_start, sync_job_id=None):
    # wait for the submitter to finish all tasks for this crawl window before advancing latest_data
    logger.info(f"Waiting for submit tasks to drain through {next_start}")
    deadline = now() + timedelta(seconds=SUBMIT_DRAIN_TIMEOUT)
    while now() < deadline:
        if sync_job_id:
            row = get_sync_job(sync_job_id)
        else:
            row = get_scheduler_row(connection_id, function_name)
        if row.get("latest_data") == next_start:
            return
        if should_update_latest_data(row):
            if sync_job_id:
                advance_sync_job_latest_data(sync_job_id, row)
            else:
                advance_latest_data(connection_id, function_name, row)
            return
        sleep(SUBMIT_DRAIN_POLL)
    raise PokedexException(
        f"Submit tasks did not drain through {next_start} in {SUBMIT_DRAIN_TIMEOUT}s",
        500,
        origin="trackstar",
