    def get_orders(
        self, start, end, first_crawl, first_loop, page_token=None, sync_job_id=None
    ):
        if first_loop:
            self.get_warehouse_to_metadata_map()
            self.kit_ids = {}
            products = []
            if not self.in_perm_validator():
                Product(self).check_first_crawl_complete()
                products = Product(self).get_all_resources(
                    query_params={"is_kit": {"eq": True}}
                )

            for product in products:
                # Get bc old products arent backfilled with is_kit
                if product.get("is_kit"):
                    self.kit_ids[product["id"]] = product

        query_params = {
            "pgsiz": PAGE_SIZE,
            "detail": "All",
            "sort": "ReadOnly.LastModifiedDate",
        }

        query_start = page_token or get_3pl_central_start_time(
            start, self.warehouse_to_metadata
        )
        query_params["rql"] = f"ReadOnly.LastModifiedDate=ge={query_start}"

        response = self.get_orders_page(query_params)
        page_size = query_params["pgsiz"]
        orders = response["ResourceList"]

        next_token = None
        if len(orders) == page_size:
            next_token = orders[-1]["ReadOnly"]["LastModifiedDate"].split(".")[
                0
            ]  # RQL doesn't support millisecond queries
            # handle case of next_token being the same as the query_start
            curr_page = 1
            order_ids_seen = {order["ReadOnly"]["OrderId"] for order in orders}
            while next_token == query_start:
                curr_page += 1
                query_params["pgnum"] = curr_page
                response = self.get_orders_page(query_params)
                curr_page = query_params["pgnum"]
                page_size = query_params["pgsiz"]
                current_orders = response["ResourceList"]
                for order in current_orders:
                    if order["ReadOnly"]["OrderId"] not in order_ids_seen:
                        order_ids_seen.add(order["ReadOnly"]["OrderId"])
                        orders.append(order)
                    # TODO possible data loss here if we see an order we've already seen.
                    # could indicate an order was updated while we were paginating and pages got reordered

                if len(current_orders) == page_size:
                    next_token = current_orders[-1]["ReadOnly"][
                        "LastModifiedDate"
                    ].split(".")[0]  # RQL doesn't support millisecond queries
                else:
                    next_token = None
            if next_token and next_token > dt_to_str(end):
                next_token = None

        next_start = None
        if next_token:
            # LastModifiedDate is in warehouse local time; the latest utc reading of it
            # makes the next window's query start at exactly next_token again
            next_token_dts = []
            for warehouse in self.warehouse_to_metadata.values():
                next_token_dts.append(
                    str_to_dt(format_date(next_token, warehouse["timezone"]))
                )
            if not next_token_dts:
                next_token_dts.append(str_to_dt(format_date(next_token, None)))
            next_token_dt = max(next_token_dts)
            if next_token_dt.date() > start.date() and next_token_dt < end:
                next_token = None
                next_start = next_token_dt

